<script setup lang="ts">
import type {Product} from '@ellas/shared';
const props=defineProps<{admin?:boolean;inline?:boolean}>();const emit=defineEmits<{close:[]}>();const message=ref('');const busy=ref(false);const failure=ref('');const messages=ref<{role:'user'|'assistant';text:string;products?:Product[]}[]>([]);const actions=ref<{id:string;token:string;summary:string;expiresAt:string;kind:string}[]>([]);const scrollArea=ref<HTMLElement>();const inputElement=ref<HTMLTextAreaElement>();onMounted(()=>inputElement.value?.focus());const {mutate}=useStaff();
const {data:status}=await useFetch<{configured:boolean}>('/api/assistant/status');
async function ask(){if(busy.value||!message.value.trim())return;const input=message.value.trim();busy.value=true;failure.value='';messages.value.push({role:'user',text:input});message.value='';try{const body={message:input,consent:true};const result=props.admin?await mutate<{answer:string;products:Product[];actions:typeof actions.value}>('/api/admin/assistant/chat',{method:'POST',body}):await $fetch<{answer:string;products:Product[];actions:typeof actions.value}>('/api/assistant/chat',{method:'POST',body,timeout:90000});messages.value.push({role:'assistant',text:result.answer,products:result.products});actions.value.push(...result.actions);await nextTick();scrollArea.value?.scrollTo({top:scrollArea.value.scrollHeight,behavior:'smooth'});}catch(e){if(messages.value.at(-1)?.role==='user'&&messages.value.at(-1)?.text===input)messages.value.pop();failure.value=errorMessage(e,'El asesor no está disponible. Tu trabajo se conserva; vuelve a intentarlo.');message.value=input;}finally{busy.value=false;}}
</script>
<template><section :class="['assistant-panel',{inline}]" :role="inline?undefined:'dialog'" :aria-modal="inline?undefined:false" :aria-label="admin?'Asistente del administrador':'Asesor de Uniformes Ellas'" @keydown.esc="!inline&&emit('close')"><header><span class="assistant-symbol">✳</span><div><h2>{{admin?'Asistente del equipo':'¿Lo elegimos juntos?'}}</h2><span>{{admin?'Gestión con revisión humana':'Asesor de Uniformes Ellas'}} · IA</span></div><button v-if="!inline" class="icon-button" aria-label="Cerrar asesor" @click="emit('close')"><AppIcon name="X" :size="18"/></button></header><div ref="scrollArea" class="assistant-messages" role="log" aria-live="polite"><div v-if="!messages.length" class="assistant-welcome"><h3>{{admin?'Menos copiar. Más gestionar.':'Cuéntame qué necesita tu equipo.'}}</h3><p>{{admin?'Puedo buscar solicitudes, resumirlas y preparar cambios para que los revises. Para mensajes de otros canales, usa la entrada asistida.':'Te ayudo a comparar tejidos, gramajes y prendas del catálogo. Precio y disponibilidad los confirma el equipo de la tienda.'}}</p><div class="assistant-suggestions"><button v-for="example in admin?['Busca las últimas solicitudes','Resume la solicitud UE-2026-0309682444']:['Busco camisetas de algodón','¿Qué diferencia hay entre JT150 y TSRA190?']" :key="example" @click="message=example">{{example}} <AppIcon name="ArrowUpRight" :size="13"/></button></div></div><article v-for="(item,index) in messages" :key="index" :class="['assistant-message',item.role]"><small>{{item.role==='user'?'Tú':admin?'Asistente del equipo':'Uniformes Ellas · IA'}}</small><p class="preserve-lines">{{item.text}}</p><div v-if="item.products?.length" class="assistant-products"><div v-for="p in item.products" :key="p.reference"><img :src="p.imageSmall" :alt="p.name" width="45" height="57"/><div><b>{{p.name}}</b><small>{{p.reference}}</small><NuxtLink :to="{path:'/hacer-pedido',query:{ref:p.reference}}" @click="!inline&&emit('close')">Configurar <AppIcon name="ArrowRight" :size="12"/></NuxtLink><CompareButton :reference="p.reference"/></div></div></div></article><p v-if="busy" class="assistant-thinking" role="status">Consultando los datos…</p><p v-if="failure" class="alert error" role="alert">{{failure}}</p><ActionReview v-for="action in actions" :key="action.id" :action="action"/></div><footer><p v-if="status && !status.configured" class="field-error">El asesor aún no está configurado. El buscador y tu pedido siguen disponibles.</p><form @submit.prevent="ask"><label class="sr-only" for="assistant-message">Tu consulta al asesor</label><textarea ref="inputElement" id="assistant-message" v-model="message" rows="2" maxlength="2000" :placeholder="admin?'Busca una solicitud o prepara un cambio…':'Ej. camisetas de algodón para un equipo de 20…'" :disabled="busy" @keydown.enter.exact.prevent="ask"/><button type="submit" class="icon-button" aria-label="Enviar consulta al asesor" :disabled="busy||!message.trim()"><AppIcon name="ArrowUpRight"/></button></form><small>El texto se procesa con OpenAI. Evita datos personales que no hagan falta. <NuxtLink to="/privacidad">Privacidad</NuxtLink></small></footer></section></template>
